import hashlib
from pathlib import Path

def sha256(p):
    h = hashlib.sha256()
    with open(p,'rb') as f:
        for c in iter(lambda: f.read(1<<20), b''):
            h.update(c)
    return h.hexdigest()

with open('{{manifest_file}}','w') as out:
    for p in sorted(Path('{{scan_dir}}').rglob('*')):
        if p.is_file():
            out.write(f'{sha256(p)}  {p}\n')
print('manifest done')
